def find_multiple():
    # Define the choices
    choices = [36, 15, 17, 5, 7]

    # Define the divisors
    divisors = [9, 12]

    # Function to check if a number is divisible by all divisors
    def is_divisible_by_all(number, divisors):
        for divisor in divisors:
            if number % divisor != 0:
                return False
        return True

    # Find the number that is divisible by both 9 and 12
    for choice in choices:
        if is_divisible_by_all(choice, divisors):
            return choice

answer = find_multiple()
